import "timer" for Timer

// Timer has no cancel/clear method - accessing it produces a runtime error
var f = Fiber.new { Timer.cancel }
var r = f.try()
// try() returns the value the fiber completed with (Timer.cancel evaluates to something)
// but on error, returns null. Either way, error state tells us.
System.print(f.error != null) // expect: true
